package br.com.saraivamotos.controller;import java.util.*;import br.com.saraivamotos.dto.*;import br.com.saraivamotos.security.AuthenticatedUser;import br.com.saraivamotos.service.ContaReceberService;import jakarta.validation.Valid;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/contas-receber") public class ContaReceberController{private final ContaReceberService service;public ContaReceberController(ContaReceberService s){service=s;}@GetMapping public List<ContaReceberResponse> listar(){return service.listar();}@PostMapping("/{id}/recebimentos")public RecebimentoResponse receber(@PathVariable Long id,@RequestHeader("Idempotency-Key")String key,@Valid @RequestBody RecebimentoRequest r,@AuthenticationPrincipal AuthenticatedUser u){return service.registrar(id,key,r,u);}@PostMapping("/recebimentos/{id}/estornar")public RecebimentoResponse estornar(@PathVariable Long id,@Valid @RequestBody EstornoRecebimentoRequest r,@AuthenticationPrincipal AuthenticatedUser u){return service.estornar(id,r,u);}}
